mapper.select:
SELECT bo.*, bi.name as borrower_name, bi.phone as borrower_phone, b.title as book_title, b.isbn as book_isbn FROM borrow_order bo LEFT JOIN borrower_info bi ON bo.borrower_id = bi.id LEFT JOIN book_info b ON bo.book_id = b.id WHERE bo.deleted = 0
AND bo.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND bo.borrower_id = #{borrowerId}
AND bo.book_id = #{bookId}
AND bo.status = #{status}
AND bo.deposit_status = #{depositStatus}
AND bo.pay_status = #{payStatus}
ORDER BY bo.create_time DESC
